77: // WithURL sets the URL for where telemetry information is flushed to.
78: // For the URL, uploading through agent goes through
79: //
80: //	${AGENT_URL}/telemetry/proxy/api/v2/apmtelemetry
81: //
82: // for agentless:
83: //
84: //	https://instrumentation-telemetry-intake.datadoghq.com/api/v2/apmtelemetry
85: //
86: // with an API key
87: func WithURL(agentless bool, agentURL string) Option {
88: 	return func(client *client) {
89: 		if agentless {
90: 			client.URL = getAgentlessURL()
91: 		} else {
92: 			u, err := url.Parse(agentURL)
93: 			if err == nil {
94: 				u.Path = "/telemetry/proxy/api/v2/apmtelemetry"
95: 				client.URL = u.String()
96: 			} else {
97: 				log("Agent URL %s is invalid, switching to agentless telemetry endpoint", agentURL)
98: 				client.URL = getAgentlessURL()
99: 			}
100: 		}
101: 	}
102: }
103: 
104: func getAgentlessURL() string {
105: 	agentlessEndpointLock.RLock()
106: 	defer agentlessEndpointLock.RUnlock()
107: 	return agentlessURL
108: }
